import { buildContainer } from "./src/composition.ts";
import { buildServices } from "./src/server/services.ts";

const container = await buildContainer();
const services = buildServices(container);
const userId = "local";
// Live PocketSmith balances pulled 2026-08-19 (cents)
const cashOnHandCents = 26232 + 23872 + 10 + 6206080; // MAC Casual, MAC Buffer, ANZ Expenses, ANZ Emergency
const cardOwedCents = 448112; // NAB card #7280

const now = new Date();
const period = new Intl.DateTimeFormat("en-CA", { timeZone: container.config.timezone, year: "numeric", month: "2-digit" }).format(now).slice(0, 7);
const grid = await services.envelopes.getGrid(userId, period);
const topLevel = grid.rows.filter((r: any) => r.parentId === null);
const leafLeftCents = topLevel.reduce((s: number, r: any) => s + r.leftCents, 0);
const incomeLeftCents = grid.income.reduce((s: number, i: any) => s + i.carryoverCents + i.varianceCents, 0);
const totalLeftCents = leafLeftCents + incomeLeftCents;
const awaitingIncomeCents = grid.income.reduce((s: number, i: any) => s + (i.awaitingCents ?? 0), 0);
const reconciledDeltaCents = cashOnHandCents - cardOwedCents - (totalLeftCents - awaitingIncomeCents);
const uncat = grid.unresolvedActivityCents ?? 0;
console.log(JSON.stringify({
  period, cashOnHandCents, cardOwedCents, leafLeftCents, incomeLeftCents, totalLeftCents,
  awaitingIncomeCents, reconciledDeltaCents, uncategorisedActivityCents: uncat,
  unexplainedDeltaCents: reconciledDeltaCents - uncat,
}, null, 1));
await container.store.close();
EOF
